(()=>{const dialog=document.querySelector('#photo-dialog'),full=document.querySelector('#full-photo');document.addEventListener('click',e=>{const button=e.target.closest('[data-image]');if(!button)return;full.src=button.dataset.image;full.style.filter=button.dataset.brightness?"brightness("+button.dataset.brightness+")":"none";full.alt=button.querySelector('img')?.alt||'Foto de la reforma';dialog.showModal()});document.querySelector('#close-photo').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});fetch('datos/javier-cocinas.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{const works=document.querySelector('#works');const projects=(data.trabajos||[]).filter(t=>t.antes&&t.despues);if(!projects.length)return;const fragment=document.createDocumentFragment();projects.forEach(t=>{const article=document.createElement('article');article.className='work';const title=document.createElement('h3');title.textContent=t.titulo||'Reforma de cocina';article.append(title);const pair=document.createElement('div');pair.className='comparison';[['ANTES',t.antes],['DESPUÉS',t.despues]].forEach(([label,url])=>{const figure=document.createElement('figure');if(label==='DESPUÉS')figure.className='after';const caption=document.createElement('figcaption');caption.textContent=label;const button=document.createElement('button');button.type='button';button.className='photo';button.dataset.image=url;button.setAttribute('aria-label','Ampliar '+label.toLowerCase()+' de '+title.textContent);const img=document.createElement('img');img.src=url;img.alt=label+' · '+title.textContent;img.loading='lazy';button.append(img);figure.append(caption,button);pair.append(figure)});article.append(pair);if(t.descripcion){const p=document.createElement('p');p.textContent=t.descripcion;article.append(p)}fragment.append(article)});works.replaceChildren(fragment)}).catch(()=>{})})();
